using System.IO;
using System.IO.Compression;
using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
namespace CremaTools;

public class VaultEnvelope { public int Version { get; set; } = 1; public string Label { get; set; } = ""; public int Iterations { get; set; } = 600000; public string Salt { get; set; } = ""; public string PasswordKey { get; set; } = ""; public string RecoveryKey { get; set; } = ""; }
public class VaultFile { public string Id { get; set; } = ""; public string Name { get; set; } = ""; public string Category { get; set; } = ""; public long Size { get; set; } public string Hash { get; set; } = ""; public DateTime Added { get; set; } = DateTime.UtcNow; public string Poids => Storage.Size(Size); }
public class VaultIndex { public List<string> Categories { get; set; } = ["Personnel", "Identité", "RIB", "Impôts", "Société 1"]; public List<VaultFile> Files { get; set; } = []; }
public sealed class VaultEngine : IDisposable
{
    static readonly byte[] Aad = Encoding.UTF8.GetBytes("CremaTools:Vault:v1"); private byte[]? key;
    public string DirectoryPath { get; private set; } = ""; public VaultIndex Index { get; private set; } = new(); public bool IsOpen => key is not null;
    static byte[] Encrypt(byte[] plain, byte[] key) { var nonce = RandomNumberGenerator.GetBytes(12); var tag = new byte[16]; var cipher = new byte[plain.Length]; using (var aes = new AesGcm(key, 16)) aes.Encrypt(nonce, plain, cipher, tag, Aad); return [.. nonce, .. tag, .. cipher]; }
    static byte[] Decrypt(byte[] bytes, byte[] key) { if (bytes.Length < 28) throw new CryptographicException("Coffre incomplet."); var plain = new byte[bytes.Length - 28]; using (var aes = new AesGcm(key, 16)) aes.Decrypt(bytes.AsSpan(0, 12), bytes.AsSpan(28), bytes.AsSpan(12, 16), plain, Aad); return plain; }
    static byte[] Derive(string pass, VaultEnvelope env) => Rfc2898DeriveBytes.Pbkdf2(pass, Convert.FromBase64String(env.Salt), env.Iterations, HashAlgorithmName.SHA256, 32);
    static void ValidateEnvelope(VaultEnvelope e) { if (e.Version != 1 || e.Iterations < 100000 || e.Iterations > 2000000) throw new Exception("Format de coffre non pris en charge."); }
    void SaveIndex() { EnsureOpen(); var plain = JsonSerializer.SerializeToUtf8Bytes(Index); try { AtomicBytes(Path.Combine(DirectoryPath, "index.enc"), Encrypt(plain, key!)); } finally { CryptographicOperations.ZeroMemory(plain); } }
    static void AtomicBytes(string file, byte[] bytes) { var tmp = file + "." + Guid.NewGuid().ToString("N") + ".tmp"; File.WriteAllBytes(tmp, bytes); File.Move(tmp, file, true); }
    public string Create(string parent, string label, string password) { if (password.Length < 12) throw new Exception("Choisissez une phrase secrète d’au moins 12 caractères."); Lock(); DirectoryPath = Path.Combine(parent, Guid.NewGuid().ToString("N")); Directory.CreateDirectory(DirectoryPath); key = RandomNumberGenerator.GetBytes(32); var recovery = RandomNumberGenerator.GetBytes(32); var env = new VaultEnvelope { Label = label, Salt = Convert.ToBase64String(RandomNumberGenerator.GetBytes(16)) }; var derived = Derive(password, env); try { env.PasswordKey = Convert.ToBase64String(Encrypt(key, derived)); env.RecoveryKey = Convert.ToBase64String(Encrypt(key, recovery)); Storage.Write(Path.Combine(DirectoryPath, "vault.json"), env); Index = new(); SaveIndex(); return Convert.ToHexString(recovery); } finally { CryptographicOperations.ZeroMemory(derived); CryptographicOperations.ZeroMemory(recovery); } }
    public void Unlock(string directory, string password, bool recovery = false) { Lock(); var env = Storage.Read(Path.Combine(directory, "vault.json"), new VaultEnvelope()); ValidateEnvelope(env); var wrapping = recovery ? Convert.FromHexString(password.Replace(" ", "").Replace("-", "")) : Derive(password, env); byte[]? opened = null; try { opened = Decrypt(Convert.FromBase64String(recovery ? env.RecoveryKey : env.PasswordKey), wrapping); var plain = Decrypt(File.ReadAllBytes(Path.Combine(directory, "index.enc")), opened); try { Index = JsonSerializer.Deserialize<VaultIndex>(plain) ?? throw new Exception("Index du coffre invalide."); } finally { CryptographicOperations.ZeroMemory(plain); } DirectoryPath = directory; key = opened; opened = null; } finally { CryptographicOperations.ZeroMemory(wrapping); if (opened is not null) CryptographicOperations.ZeroMemory(opened); } }
    public void ChangePassword(string password) { EnsureOpen(); if (password.Length < 12) throw new Exception("Minimum 12 caractères."); var env = Storage.Read(Path.Combine(DirectoryPath, "vault.json"), new VaultEnvelope()); env.Salt = Convert.ToBase64String(RandomNumberGenerator.GetBytes(16)); var derived = Derive(password, env); try { env.PasswordKey = Convert.ToBase64String(Encrypt(key!, derived)); Storage.Write(Path.Combine(DirectoryPath, "vault.json"), env); } finally { CryptographicOperations.ZeroMemory(derived); } }
    public void Add(string file, string category) { EnsureOpen(); var info = new FileInfo(file); if (info.Length > 100 * 1024 * 1024) throw new Exception("Le coffre accepte des documents de 100 Mo maximum chacun."); var bytes = File.ReadAllBytes(file); string id = Guid.NewGuid().ToString("N"); try { var record = new VaultFile { Id = id, Name = info.Name, Category = category, Size = bytes.Length, Hash = Convert.ToHexString(SHA256.HashData(bytes)) }; AtomicBytes(Path.Combine(DirectoryPath, id + ".enc"), Encrypt(bytes, key!)); Index.Files.Add(record); try { SaveIndex(); } catch { Index.Files.Remove(record); File.Delete(Path.Combine(DirectoryPath, id + ".enc")); throw; } } finally { CryptographicOperations.ZeroMemory(bytes); } }
    public byte[] Read(VaultFile file) { EnsureOpen(); if (!Guid.TryParseExact(file.Id, "N", out _)) throw new Exception("Entrée de coffre invalide."); var plain = Decrypt(File.ReadAllBytes(Path.Combine(DirectoryPath, file.Id + ".enc")), key!); if (Convert.ToHexString(SHA256.HashData(plain)) != file.Hash) { CryptographicOperations.ZeroMemory(plain); throw new CryptographicException("Le document a changé ou est endommagé."); } return plain; }
    public void Export(VaultFile file, string destination) { var bytes = Read(file); try { using var output = new FileStream(destination, FileMode.CreateNew, FileAccess.Write); output.Write(bytes); } finally { CryptographicOperations.ZeroMemory(bytes); } }
    public void Remove(VaultFile file) { EnsureOpen(); Index.Files.Remove(file); try { SaveIndex(); } catch { Index.Files.Add(file); throw; } File.Delete(Path.Combine(DirectoryPath, file.Id + ".enc")); }
    public void AddCategory(string category) { EnsureOpen(); category = category.Trim(); if (category.Length == 0 || Index.Categories.Contains(category)) throw new Exception("Choisissez un nom de catégorie différent."); Index.Categories.Add(category); SaveIndex(); }
    public void RenameCategory(string old, string next) { EnsureOpen(); next = next.Trim(); if (next.Length == 0 || Index.Categories.Contains(next)) throw new Exception("Choisissez un nom différent."); Index.Categories[Index.Categories.IndexOf(old)] = next; foreach (var file in Index.Files.Where(f => f.Category == old)) file.Category = next; SaveIndex(); }
    public void Backup(string destination) { EnsureOpen(); using var zip = ZipFile.Open(destination, ZipArchiveMode.Create); foreach (var file in Directory.GetFiles(DirectoryPath).Where(f => Path.GetExtension(f) == ".enc" || Path.GetFileName(f) == "vault.json")) zip.CreateEntryFromFile(file, Path.GetFileName(file), CompressionLevel.NoCompression); }
    public static string Restore(string archive, string parent) { var target = Path.Combine(parent, Guid.NewGuid().ToString("N")); Directory.CreateDirectory(target); try { using var zip = ZipFile.OpenRead(archive); if (zip.Entries.Count > 10000 || !zip.Entries.Any(e => e.FullName == "vault.json") || !zip.Entries.Any(e => e.FullName == "index.enc")) throw new Exception("Ce fichier n’est pas une sauvegarde de coffre."); long total = 0; foreach (var entry in zip.Entries) { if (entry.FullName != Path.GetFileName(entry.FullName) || entry.FullName.Contains('\\') || entry.FullName.Contains(':') || entry.Length > 101L * 1024 * 1024 || (total += entry.Length) > 10L * 1024 * 1024 * 1024) throw new Exception("Archive de sauvegarde non valide."); if (entry.FullName != "vault.json" && entry.FullName != "index.enc" && !(entry.FullName.EndsWith(".enc") && Guid.TryParseExact(Path.GetFileNameWithoutExtension(entry.FullName), "N", out _))) throw new Exception("Fichier de sauvegarde inattendu."); entry.ExtractToFile(Path.Combine(target, entry.FullName), false); } var env = Storage.Read(Path.Combine(target, "vault.json"), new VaultEnvelope()); ValidateEnvelope(env); return target; } catch { Directory.Delete(target, true); throw; } }
    void EnsureOpen() { if (key is null) throw new Exception("Déverrouillez le coffre."); }
    public void Lock() { if (key is not null) CryptographicOperations.ZeroMemory(key); key = null; Index = new(); }
    public void Dispose() => Lock();
}
